import {workspaceThreadShow} from './workspace-thread-view.js';
import {learningRoles,adoptionGuidance,workspaceBehaviors} from './workspace-thread-content.js';
import {beforeMoments,wsScenes,wsReady,wsNextHint,project,calendarTopics,chatExercises,workspaceLessons,workspaceGuide,aiSections,networkNodes} from './workspace-model.js';
const b=(id,label,value='',kind='primary',disabled=false)=>`<button class="ws-${kind}" data-ws="${id}" ${value?`data-value="${value}"`:''} ${disabled?'disabled title="Complete the current interaction before continuing."':''} ${['tab','tab-active'].includes(kind)?`aria-pressed="${kind==='tab-active'}"`:''}>${label}</button>`;
const chip=(text)=>`<span class="ws-chip">${text}</span>`;
const appTag=(name)=>`<span class="ws-app"><i>${({Gmail:'✉',Calendar:'▦',Meet:'◉',Chat:'◌',Spaces:'⊞',Drive:'△',Sheets:'▤',Docs:'▧',Gemini:'✧'})[name]||'◈'}</i>${name}</span>`;
const members=()=>'<div class="ws-avatars"><span title="Account Executive">AE</span><span title="Presales">PS</span><span title="Technical Team">TT</span></div>';
function email(s,after=false){return `<div class="ws-mail"><div class="ws-mail-meta"><span class="ws-person">C</span><div><strong>Customer</strong><small>To you · ${after?'original request':'08:03'}</small></div><span class="ws-mail-date">Planning day</span></div><h3>Cloud migration discussion</h3><p>We’d like to discuss our cloud migration plan next week.</p><div class="ws-mail-attachment">▤ Assessment.xlsx</div>${after?`<div class="ws-mail-action">${b('next','SCHEDULE MEETING →')}<small>Carry the request into an event.</small></div>`:''}</div>`;}
function before(s){const m=beforeMoments[s.before];const tiles=[['email','Customer request','Inbox'],['download','Assessment.xlsx','Downloads'],['edit','Local changes','Your laptop'],['versions','Assessment_FINAL_FIX.xlsx','Email attachment'],['schedule','Tuesday? Which time?','Messages'],['meeting','Migration discussion','Meeting'],['notes','Meeting notes','Personal document'],['attachment','Send the attachment again?','Messages']].slice(0,Math.min(s.before+1,8));let current='';switch(m.kind){case 'email':current=email(s);break;case 'versions':current=`<div class="ws-version-stack">${['Assessment.xlsx','Assessment_v2.xlsx','Assessment_FINAL.xlsx','Assessment_FINAL_FIX.xlsx'].map((f,i)=>`<div style="--paper-index:${i}"><span>▤</span>${f}<small>${['Original','Local update','Shared copy','Another edit'][i]}</small></div>`).join('')}</div>`;break;case 'schedule':current='<div class="ws-messages"><p><b>You</b>Could we meet on Tuesday?</p><p><b>Customer</b>Which time works?</p><p><b>Presales</b>I have another call that morning.</p></div>';break;case 'latest':current='<div class="ws-last-question"><span class="ws-person">T</span><blockquote>“Which file is the latest?”</blockquote><small>Three people. Several copies. No clear working version.</small></div>';break;default:current=`<div class="ws-before-focus"><span>${({download:'⇣',edit:'▤',meeting:'◉',notes:'▧',attachment:'✉'})[m.kind]}</span><h3>${m.title}</h3><p>${m.detail}</p></div>`;}
return `<div class="ws-scene-heading"><span class="ws-overline">BEFORE / THE HANDOFFS</span><h2>${m.title}</h2></div><div class="ws-fragment-layout"><div class="ws-fragments" aria-label="Places where project context is accumulating">${tiles.map(([kind,title,where],i)=>`<div class="ws-fragment ${kind===m.kind?'current':''}" style="--fragment-index:${i}"><small>${where}</small><span>${title}</span></div>`).join('')}</div><div class="ws-current-fragment">${current}</div></div><p class="ws-scene-note">Illustrative moments from a fragmented workday; not a measured time comparison.</p>`;}
function calendar(s){return `<div class="ws-scene-heading">${appTag('Calendar')}<h2>Find a time. Bring the context.</h2></div><div class="ws-calendar-layout"><div class="ws-event"><div class="ws-event-title">Cloud migration discussion</div><p class="ws-event-origin">From the customer’s email · next week</p><div class="ws-event-row"><span>PEOPLE</span><p>You · organizer<br>Customer · ${s.event?'invited, response pending':'to invite'}${s.team?'<br>Presales · added':''}</p>${b('invite',s.team?'Team added ✓':'INVITE TEAM','','secondary',s.team)}</div><div class="ws-event-row"><span>WHEN</span><p>${s.slot||'Choose a proposed time'}</p>${b('find-time',s.availability?'Availability shown ✓':'FIND A TIME','','secondary',s.availability)}</div><div class="ws-event-row"><span>JOIN</span><p>${s.meetLink?'Meet link attached':'No meeting link yet'}</p>${b('meet-link',s.meetLink?'Meet added ✓':'ADD GOOGLE MEET','','secondary',s.meetLink)}</div><div class="ws-event-row"><span>PREPARE</span><p>${s.attachment?'Assessment.xlsx · named guests’ access reviewed':'Bring the same assessment'}</p>${b('attach',s.attachment?'File attached ✓':'ATTACH FILE','','secondary',s.attachment)}</div>${s.event?'<div class="ws-success">Event created in this simulation. The invitation contains the time, Meet link and assessment. Customer response is still pending.</div>':b('create-event','CREATE EVENT →','','primary',!(s.slot&&s.team&&s.meetLink&&s.attachment))}</div><div class="ws-availability">${s.availability?`<span class="ws-overline">FIND A TIME / EXAMPLE AVAILABILITY</span><div class="ws-slot-head"><span>Next week</span><span>You</span><span>PS</span><span>Customer</span></div>${[['Tue 09:00','Busy','Busy'],['Tue 10:30','Free','Free'],['Wed 14:00','Free','Free']].map(([slot,a,p])=>`<button class="ws-slot ${s.slot===slot?'selected':''}" data-ws="slot" data-value="${slot}" ${a==='Busy'?'disabled':''}><b>${slot}</b><span class="${a==='Free'?'free':'busy'}">${a}</span><span class="${p==='Free'?'free':'busy'}">${p}</span><span>Confirm</span></button>`).join('')}<p class="ws-mini-note">Internal calendars are shared in this example. Customer availability still needs confirmation.</p>`:'<div class="ws-calendar-placeholder"><span>▦</span><p>Compare shared availability before proposing a time.</p></div>'}</div></div>`;}
function meet(s){return `<div class="ws-scene-heading">${appTag('Meet')}<h2>The meeting starts with context.</h2><p>Next week · meeting day · time confirmed for this scenario</p></div><div class="ws-context-ribbon">▦ Cloud migration discussion <span>${s.slot}</span><span>▤ Assessment.xlsx</span></div><div class="ws-meeting"><div class="ws-meeting-people">${[['C','Customer','We need to assess our on-premise workload.'],['AE','You / AE','What concerns you most about the move?'],['PS','Presales','Let’s map dependencies before planning cutover.']].map(([initial,name,quote],i)=>`<article class="${s.meetingStarted?'speaking':''}" style="--speaker:${i}"><span>${initial}</span><b>${name}</b>${s.meetingStarted?`<p>${quote}</p>`:'<small>Ready to discuss</small>'}</article>`).join('')}</div>${!s.meetingStarted?b('start-meet','START THE MEETING →'):s.notes?`<div class="ws-meeting-notes"><span class="ws-sim">SIMULATED CONTENT</span><strong>MEETING NOTES</strong><div><p><b>Key requirements</b>${project.requirements.join('<br>')}</p><p><b>Open questions</b>${project.questions.join('<br>')}</p></div></div>`:b('notes','CAPTURE MEETING CONTEXT →')}<p class="ws-mini-note">Conceptual note assistance. Gemini features require an eligible plan and applicable settings; review notes before using them.</p></div>`;}
function spaceContent(s){return {Discussion:'<p><b>AE</b> Let’s continue the assessment here. The meeting notes and working files belong with this project.</p><p><b>Presales</b> I’ll map dependencies. Technical team: please review what information we still need.</p>','Meeting context':`<h4>Cloud migration discussion</h4><p>${project.requirements.join(' · ')}</p><span class="ws-linked">▧ Meeting Notes · from the meeting</span>`,Files:'<div class="ws-linked">△ Architecture.pdf</div><div class="ws-linked">▤ Assessment.xlsx</div><div class="ws-linked">▧ Meeting Notes</div><div class="ws-linked">▧ Proposal Draft</div>',Links:'<p><b>Project area</b><br>Shared working files in Drive</p><p><b>Meeting event</b><br>The original discussion and assessment link</p>',Updates:'<p><b>Next action</b> Presales to map dependencies.</p><p><b>Open</b> Confirm database size and the target timeline with the customer.</p>'}[s.spaceTab];}
function collaborate(s){return `<div class="ws-scene-heading"><span class="ws-overline">AFTER THE MEETING</span><h2>Where does the conversation continue?</h2></div><div class="ws-channel-choices"><button class="${s.channel==='chat'?'selected':''}" data-ws="chat"><span>◌</span><b>USE CHAT</b><small>Quick communication</small></button><button class="${s.channel==='space'?'selected':''}" data-ws="space"><span>⊞</span><b>CREATE A SPACE</b><small>Project · Team · Topic · Initiative</small></button></div>${s.channel==='chat'?`<div class="ws-chat-demo">${appTag('Chat')}<div class="ws-chat-bubble"><small>You → Presales</small>Can you send me the assessment?</div><div class="ws-chat-bubble response"><small>Presales → You</small>Here’s the working file. Let’s keep project decisions together.</div><p class="ws-mini-note">A focused exchange between people. For ongoing project context, create a named Space. History still depends on settings.</p>${b('space','ORGANIZE THIS PROJECT IN A SPACE →')}</div>`:s.channel==='space'?`<div class="ws-project-space"><div class="ws-space-title"><div>${appTag('Spaces')}<h3>${project.name}</h3></div>${members()}</div><p class="ws-mini-note">AE · Presales · Technical Team</p><div class="ws-tabs" role="group" aria-label="Space content">${['Discussion','Meeting context','Files','Links','Updates'].map(t=>b('space-tab',t,t,s.spaceTab===t?'tab-active':'tab')).join('')}</div><div class="ws-space-content" aria-live="polite">${spaceContent(s)}</div><div class="ws-context-kept">✓ A named place for the conversation, decisions and working material.</div></div>`:'<div class="ws-choice-prompt"><span>▧</span>Meeting context is ready.<br>Choose where it should continue.</div>'}`;}
function working(s){let editor='';if(s.file==='Assessment.xlsx')editor=`<div class="ws-editor-head">${appTag('Sheets')}<strong>Assessment.xlsx</strong>${members()}</div><p class="ws-mini-note">One shared Office file opened in Sheets · simulated edits</p><div class="ws-sheet"><table><thead><tr><th>Assessment</th><th>Working information</th><th>Owner</th></tr></thead><tbody><tr><td>Environment</td><td>On-premise workload</td><td>Customer</td></tr><tr class="${s.edits>=1?'edited-by-presales':''}"><td>Dependencies</td><td>${s.edits>=1?'Map application dependencies <span class="ws-cursor ps">↖ Presales</span>':'To review'}</td><td>Presales</td></tr><tr class="${s.edits>=2?'edited-by-tech':''}"><td>Database size</td><td>${s.edits>=2?'Customer to confirm <span class="ws-cursor tt">↖ Technical Team</span>':'Unknown'}</td><td>Tech team</td></tr></tbody></table></div><div class="ws-edit-action">${s.edits<2?b('edit-sheet',s.edits===0?'ADD PRESALES INPUT →':'ADD TECHNICAL TEAM INPUT →'):'<span class="ws-context-kept">✓ Both inputs saved to this working file.</span>'}</div><div class="ws-version-contrast"><span>FINAL</span><span>FINAL_v2</span><span>FINAL_FIX</span><b>One shared working file</b></div>`;else if(s.file==='Proposal Draft')editor=`<div class="ws-editor-head">${appTag('Docs')}<strong>Proposal Draft</strong>${members()}</div><article class="ws-doc-page"><h3>Migration assessment — next steps</h3><p>Assess the existing on-premise workload and clarify downtime requirements.</p>${s.doc?'<p class="ws-doc-added">Agree an assessment workshop. Confirm dependencies, database size and target timeline before defining the migration approach.<span>AE · added to shared draft</span></p>':'<p class="ws-doc-placeholder">Add the next action from the project discussion.</p>'}</article>${b('edit-doc',s.doc?'Next action added ✓':'ADD THE NEXT ACTION →','','primary',s.doc)}`;else if(s.file==='Meeting Notes')editor=`<div class="ws-editor-head">${appTag('Docs')}<strong>Meeting Notes</strong></div><article class="ws-doc-page"><span class="ws-sim">SIMULATED CONTENT</span><h3>From the same meeting</h3><p>${project.requirements.join('<br>')}</p><h4>Still to confirm</h4><p>${project.questions.join(' · ')}</p></article>`;else if(s.file==='Architecture.pdf')editor='<div class="ws-editor-head"><span class="ws-app">△ PDF preview</span><strong>Architecture.pdf</strong></div><div class="ws-pdf-concept"><span>Existing workload</span><i>→ assessment →</i><span>Proposed destination</span></div><p class="ws-mini-note">Illustrative reference file. Architecture is not yet agreed.</p>';else editor='<div class="ws-file-prompt"><span>▤</span><h3>Open the assessment.</h3><p>Bring the team into one working file.</p></div>';
return `<div class="ws-scene-heading">${appTag('Drive')}<h2>Same project. Shared working material.</h2></div><div class="ws-work-area"><div class="ws-file-list"><small>${project.name}</small>${['Architecture.pdf','Assessment.xlsx','Meeting Notes','Proposal Draft'].map(f=>`<button data-ws="file" data-value="${f}" class="${s.file===f?'selected':''}"><span>${f.includes('xlsx')?'▤':f.includes('pdf')?'△':'▧'}</span>${f}${f==='Assessment.xlsx'&&s.edits===2?' ✓':f==='Proposal Draft'&&s.doc?' ✓':''}</button>`).join('')}</div><div class="ws-file-editor" aria-live="polite">${editor}</div></div>`;}
function gemini(s){return `<div class="ws-scene-heading">${appTag('Gemini')}<h2>Ask with the work already in view.</h2></div><div class="ws-ai-context"><span class="ws-overline">SELECTED PROJECT CONTEXT</span><div>${chip('▧ Meeting Notes')}${chip('▤ Assessment.xlsx')}${chip('▧ Proposal Draft')}</div></div><div class="ws-ai-prompt"><span>✧</span><p>Summarize the migration requirements and identify open questions.</p></div>${!s.ai?b('ai','SUMMARIZE THIS PROJECT →'):`<div class="ws-ai-result"><span class="ws-sim">SIMULATED CONTENT</span><div class="ws-tabs" role="group" aria-label="Summary sections">${Object.keys(aiSections).map(t=>b('ai-tab',t,t,s.aiTab===t?'tab-active':'tab')).join('')}</div><ul>${aiSections[s.aiTab].map(x=>`<li>${x}</li>`).join('')}</ul><div class="ws-result-source">Based on the selected demo notes, assessment and proposal.</div></div>`}<p class="ws-mini-note">Conceptual assistance, not a live AI response. Review against the source material. Feature availability depends on plan, permissions and settings.</p>`;}
function followup(s){return `<div class="ws-scene-heading">${appTag('Gmail')}<h2>Return to the customer. Keep the context.</h2></div><div class="ws-followup-context">${chip('Meeting context')}${chip('Shared assessment')}${chip('Reviewed summary')}</div>${!s.draft?`<div class="ws-followup-empty"><span>✉</span><h3>The next message starts with what the team already knows.</h3>${b('draft','CREATE FOLLOW-UP →')}</div>`:`<div class="ws-draft"><div><span class="ws-sim">SIMULATED CONTENT</span><span>Draft · not sent</span></div><small>To: Customer</small><h3>Cloud migration discussion — next steps</h3><p>Thank you for discussing your migration plans.</p><p>We discussed the existing on-premise workload, the need for an assessment, and your downtime concerns.</p><p>Please confirm the workload dependencies, database size and target timeline. We suggest an assessment workshop with your technical team as the next step.</p><p>Best regards,<br>Your account team</p><div class="ws-draft-context">Based on the same meeting and project context · review before sending.</div></div>`}`;}
function final(s){return `<div class="ws-scene-heading ws-final-title"><span class="ws-overline">THE CONNECTED WORKDAY</span><h2>${s.network?'One connected way of working.':'Follow the thread of the work.'}</h2><p>${s.network?'Communication, time, meetings, files, collaboration and AI can stay connected to the work.':'The original request is still connected to the next customer conversation.'}</p></div>${s.network?`<div class="ws-network"><svg viewBox="0 0 720 280" preserveAspectRatio="none" aria-hidden="true">${[[90,40],[360,25],[630,40],[660,150],[560,250],[230,250],[60,150]].map(([x,y])=>`<path d="M360 140 Q${x} 140 ${x} ${y}"/>`).join('')}</svg><div class="ws-network-core">Customer Cloud Migration<small>THE WORK STAYS AT THE CENTER</small></div>${networkNodes.map(([name,role],i)=>`<div class="ws-network-node node-${i}"><b>${name}</b><span>${role}</span></div>`).join('')}</div><div class="ws-final-takeaways"><span>Agree time with context.</span><span>Keep the project conversation together.</span><span>Work from shared files.</span><span>Use AI with relevant context.</span></div>`:`<div class="ws-connected-sequence">${['Gmail','Calendar','Meet','Chat / Spaces','Drive','Docs / Sheets','Gemini','Gmail'].map((x,i)=>`<div><span>${i===0?'REQUEST':i===7?'FOLLOW-UP':String(i+1).padStart(2,'0')}</span><b>${x}</b>${i<7?'<i>→</i>':''}</div>`).join('')}</div>${b('network','REVEAL THE CONNECTIONS →')}`}`;}
function sceneTime(s){return s.scene==='before'?beforeMoments[s.before].time:({opening:'08:03',friction:'11:00',mail:'08:03',calendar:'09:00',meet:'Next week',collaborate:'After meeting',work:'Project work',gemini:'Review',followup:'Follow-up',final:'Connected'})[s.scene];}
function primaryText(s){return ({opening:'START THE WORKDAY →',before:s.before<8?'NEXT MOMENT →':'SEE THE PATTERN →',friction:'TRANSFORM THE WORKDAY →',mail:null,calendar:'NEXT · MEET →',meet:'NEXT · CONTINUE THE CONVERSATION →',collaborate:'NEXT · WORK TOGETHER →',work:'NEXT · USE THE CONTEXT →',gemini:'NEXT · FOLLOW UP →',followup:'REVEAL THE WORKDAY →'})[s.scene];}
export function workspaceShow(s){if(s.scene==='opening'||s.thread.active)return workspaceThreadShow(s);let body='';switch(s.scene){case 'opening':body=`<div class="ws-opening"><span class="ws-overline">A DAY AT WORK</span><h1>One request. One meeting. One project.<br><em>How much friction happens in between?</em></h1>${email(s)}</div>`;break;case 'before':body=before(s);break;case 'friction':body=`<div class="ws-friction-reveal"><div class="ws-scattered-context"><span>Request</span><span>Assessment</span><span>Messages</span><span>Notes</span></div><h2>The work is moving.<br><em>The context isn’t.</em></h2><p>Now follow the same request with the work connected.</p></div>`;break;case 'mail':body=`<div class="ws-scene-heading">${appTag('Gmail')}<h2>Back to the original request.</h2></div>${email(s,true)}`;break;case 'calendar':body=calendar(s);break;case 'meet':body=meet(s);break;case 'collaborate':body=collaborate(s);break;case 'work':body=working(s);break;case 'gemini':body=gemini(s);break;case 'followup':body=followup(s);break;case 'final':body=final(s);}
const index=wsScenes.indexOf(s.scene);return `<section class="ws-stage ws-scene-${s.scene}" aria-label="Interactive workday"><div class="ws-dayline"><div><span class="ws-person small">YOU</span><strong>${sceneTime(s)}</strong><span class="ws-day-part">${index<=2?'THE FRAGMENTED WORKDAY':index<5?'THE SAME REQUEST':index<10?'THE SAME PROJECT':'THE WHOLE PICTURE'}</span></div></div><div class="ws-timeline" aria-label="Workday progress">${Array.from({length:11},(_,i)=>`<i class="${i<=index?'passed':''} ${i===index?'current':''}"></i>`).join('')}</div><div class="ws-scene-body" aria-live="polite">${body}</div><div class="ws-scene-footer">${b('prev','← PREVIOUS','','secondary',s.scene==='opening')}<div>${!wsReady(s)&&s.scene!=='final'?`<small id="ws-interaction-hint" class="ws-interact-hint">INTERACT · ${wsNextHint(s)}</small>`:''}</div>${primaryText(s)?b('next',primaryText(s),'','primary',!wsReady(s)):s.scene==='final'&&s.network?b('reset','START AGAIN ↺','','secondary'):''}</div><div class="ws-simulation-note">Illustrative workday · SIMULATED CONTENT · No messages or invitations are sent.</div></section>`;}
export function workspaceLearn(s){const l=workspaceLessons[s.lesson];const q=chatExercises[s.quiz];let exercise='';if(l.name==='Calendar'){const t=calendarTopics.find(x=>x[0]===s.calendarTry)||calendarTopics[0];exercise=`<div class="ws-calendar-lab"><div class="ws-topic-buttons">${calendarTopics.map(([name])=>b('calendar-try',name,name,s.calendarTry===name?'tab-active':'tab')).join('')}</div><div class="ws-lab-preview" aria-live="polite"><span class="ws-overline">${t[0]}</span><p>${t[1]}</p><strong>▦ ${t[2]}</strong></div></div>`;}else if(['Chat','Spaces'].includes(l.name)){exercise=`<div class="ws-chat-training"><div class="ws-training-contrast"><span><b>CHAT</b>Quick communication.</span><span><b>SPACES</b>Ongoing project, team, topic or initiative.</span></div><p class="ws-quiz-question">${q.text}</p><div class="ws-quiz-choices">${b('classify','CHAT','CHAT',s.answer==='CHAT'?'primary':'secondary')}${b('classify','SPACE','SPACE',s.answer==='SPACE'?'primary':'secondary')}</div>${s.answer?`<div class="ws-quiz-feedback" aria-live="polite"><b>${s.answer===q.answer?'Good fit.':'Consider '+q.answer+' here.'}</b><p>${q.why}</p>${b('quiz-next','TRY ANOTHER EXAMPLE →','','secondary')}</div>`:'<p class="ws-mini-note">Choose the better starting point, then see why.</p>'}</div>`;}else exercise=`<div class="ws-practice">${b('practice',l.try,'run')}${s.practice?`<p class="ws-practice-result" aria-live="polite">${l.result}</p>`:''}</div>`;
return `<div class="ws-learn"><nav class="ws-learn-list" aria-label="Workspace learning modules">${workspaceLessons.map((m,i)=>`<button data-ws="lesson" data-value="${i}" class="${i===s.lesson?'selected':''}" aria-pressed="${i===s.lesson}">${m.name}</button>`).join('')}</nav><article class="ws-learn-content"><div class="eyebrow">WORKSPACE / LEARN THE WORKFLOW</div><h1>${l.name}</h1><div class="ws-learn-sections"><section><h3>WHAT IT IS</h3><p>${l.what}</p></section><section><h3>WHEN TO USE IT</h3><p>${l.when}</p></section><section><h3>HOW IT CONNECTS</h3><p>${l.connect}</p></section><section><h3>COMMON CUSTOMER QUESTION</h3><strong>${l.question}</strong><p>${l.answer}</p></section></div><div class="ws-learn-sections"><section><h3>WHY IT MATTERS</h3><p>${learningRoles[l.name][0]}</p></section><section><h3>WHAT TO LISTEN FOR</h3><p>${learningRoles[l.name][1]}</p></section><section><h3>WHAT NOT TO CLAIM</h3><p>${learningRoles[l.name][2]}</p></section></div><details class="ws-behavior-notes"><summary>Product behavior / demonstration boundaries</summary><p>REAL PRODUCT BEHAVIOR describes the referenced capability. All product interactions here are SIMULATED PRODUCT BEHAVIOR. Moving one request across surfaces is CONCEPTUAL STORYTELLING; no live integration is connected.</p><p>${l.name==='Meet'?workspaceBehaviors.notes.notes.join(' · '):l.name==='Gemini'?workspaceBehaviors.ai.notes.join(' · '):'Review permissions, edition availability and applicable configuration.'}</p></details><h3 class="ws-try-label">TRY IT</h3>${exercise}<a class="ws-source" href="${l.source}" target="_blank" rel="noopener noreferrer">Google guidance ↗</a><p class="ws-mini-note">Features vary by edition and configuration. This is workflow training, not an exact replica of the Google interface.</p></article></div>`;}
export function workspaceSales(s){const g=workspaceGuide(s);return `<h3>SAY</h3><p>“Let’s follow where this request goes next.”</p><h3>ASK</h3><p>${g.ask}</p><h3>LISTEN FOR</h3><p>${g.listen}${s.thread.signal?' · Customer selected: '+s.thread.signal:''}</p><h3>PROBE</h3><p>${g.probe}</p><h3>CONNECT</h3><p>Link their handoff or context problem to the moment on screen.</p><h3>CUSTOMER CONTEXT</h3><div class="ws-adoption-options">${Object.entries({workspace:'Uses Workspace',microsoft:'Satisfied with Microsoft',disconnected:'Multiple tools',whatsapp:'WhatsApp',none:'No friction'}).map(([value,label])=>b('adoption',label,value,s.thread.adoption===value?'tab-active':'tab')).join('')}</div><p>${adoptionGuidance[s.thread.adoption]}</p><h3>NEXT MOVE</h3><p>${g.next}</p>`;}
